/* Extracted from index.html. Load order is intentional. */
const demoStore='ai-jiaowu-static-demo';let demoData={aiResults:[],uploads:[]};try{demoData=Object.assign(demoData,JSON.parse(localStorage.getItem(demoStore)||'{}'))}catch{}const saveDemo=()=>localStorage.setItem(demoStore,JSON.stringify(demoData));document.getElementById('modalSave').onclick=()=>{demoData.aiResults.push({title:document.getElementById('modalTitle').textContent,createdAt:new Date().toISOString(),status:'draft'});saveDemo();alert('AI 结果已保存为草稿');closeAI()};document.addEventListener('change',e=>{if(e.target&&e.target.type==='file'&&e.target.files[0]){demoData.uploads.push(e.target.files[0].name);saveDemo()}});
